parameters.jsCode:
// INCREMENTAL, KEYED ON THE CONTACT'S LAST-MODIFIED TIMESTAMP. HubSpot bumps it on ANY change, so
// one filter carries both cases: a new contact is modified when it is created, an edited one when
// it is edited. Both come back, and the upsert on hs_object_id inserts the first and overwrites the
// second. Nothing ever asks Supabase which records it already holds — that would be one query per
// record.
//
// THE PROPERTY IS CALLED 'lastmodifieddate' ON CONTACTS, not hs_lastmodifieddate. See the note on
// the search node below; this workflow spent its whole life reading a property contacts do not
// return, so the watermark below never moved off the floor.
//
// THE FLOOR IS THE EPOCH, NOT A RECENT DATE. A recent floor silently skips every contact last
// touched before it — one edited in 2023 and left alone would never sync, and nothing would report
// it missing. On the first run the table is empty, so this pulls full history; after that the
// watermark takes over and runs are small.
const FLOOR = 0;

// THE WATERMARK IS REWOUND TWO SECONDS, not a minute. This used to say "HubSpot's clock and ours
// are not the same clock", which was wrong: the watermark is max(hs_lastmodifieddate) of the rows
// we STORED, so it is a HubSpot timestamp compared against a HubSpot filter and no machine clock
// enters into it. The only real risk is a record sharing the exact millisecond of the last one
// stored, which GT would skip. Two seconds covers that.
//
// A MINUTE WAS ACTIVELY EXPENSIVE HERE. Every contact in this portal was bulk-modified on
// 2026-09-10 between 04:23 and 12:29 — `lastmodifieddate LT 2025-09-04` matches zero of the
// 1,116,689 — so the whole population spans eight hours. A 10,000-record page covers about 260
// seconds of that range, and rewinding 60 of them discarded a quarter of every run. Compress the
// same kind of bulk edit into twenty minutes and a page covers ~10 seconds, the rewind exceeds the
// progress made, and the sync loops forever going backwards.
const REWIND_MS = 2 * 1000;

const state = {};
for (const r of $input.all()) {
  const j = r.json || {};
  if (j.source) state[j.source] = j.newest_modified;
}

// POST {"since":"2026-01-01"} to the webhook to re-read a period on purpose — after a mapping
// change, or to repair a gap — without truncating the table. The schedule and the manual trigger
// carry no body and ignore it.
let override = null;
try {
  const body = $('Webhook: Sync now').first().json.body || {};
  const t = body.since ? Date.parse(body.since) : NaN;
  if (Number.isFinite(t)) override = t;
} catch (e) { /* not triggered by the webhook */ }

const v = state.contacts ? Date.parse(state.contacts) : NaN;
const since = override !== null
  ? String(override)
  : String(Number.isFinite(v) ? Math.max(FLOOR, v - REWIND_MS) : FLOOR);

return [{ json: { since_contacts: since } }];

