={{ JSON.stringify({
  filterGroups: [{ filters: [{ propertyName: 'lastmodifieddate', operator: 'GT', value: $json.since_contacts }] }],
  sorts: [{ propertyName: 'lastmodifieddate', direction: 'ASCENDING' }],
  properties: ['email','firstname','lastname','company','state','lifecyclestage','lastmodifieddate'],
  limit: 100
}) }}

parameters.jsCode:
// HubSpot search pages come back as { results: [...] }; flatten them into the row shape
// hubspot.hubspot_contacts expects.
//
// 100 pages x 100 records = 10,000 per execution, which is not our choice: HubSpot's search API
// refuses to page past 10,000 results for ANY one query. The watermark is what gets past it — each
// run starts where the last one stopped, so a backfill completes over several runs rather than one.
// 1,116,689 contacts is ~112 runs. Nothing is lost in between; it is only slow to become complete.
const rows = [];
for (const item of $input.all()) {
  for (const r of (item.json.results || [])) {
    const p = r.properties || {};
    rows.push({
      hs_object_id: Number(r.id),
      email: p.email || null,
      firstname: p.firstname || null,
      lastname: p.lastname || null,
      company: p.company || null,
      state: p.state || null,
      lifecyclestage: p.lifecyclestage || null,
      // HUBSPOT CALLS THIS 'lastmodifieddate' ON CONTACTS. Only companies, deals and tickets carry
      // hs_lastmodifieddate; a contact returns nothing for it even when it is named explicitly in
      // the request, so this line used to store null on every row — and the watermark, which is
      // max(hs_lastmodifieddate), stayed null with it. Our COLUMN keeps the hs_ name so all three
      // mirror tables read alike; it is the SOURCE property that differs.
      hs_lastmodifieddate: p.lastmodifieddate || null,
      synced_at: new Date().toISOString(),
    });
  }
}
// ONE item carrying the whole batch. The upsert below takes the array as a single parameter, and
// ten thousand separate statements is not a sync, it is an outage.
return rows.length ? [{ json: { rows } }] : [];
